const body = $json.body ?? $json;
if (!body.imageDataUrl && !body.imageUrl && !body.query) throw new Error('SCAN_INPUT_REQUIRED');
const content = [{ type: 'input_text', text: `Identifikasi makanan pada gambar dan estimasikan zat gizi untuk porsi yang terlihat. Konteks: ${body.query || 'tidak ada'}. Jika gambar ambigu gunakan nama netral dan estimasi konservatif.` }];
if (body.imageDataUrl || body.imageUrl) content.push({ type: 'input_image', image_url: body.imageDataUrl || body.imageUrl, detail: 'low' });
const schema = { type: 'object', additionalProperties: false, required: ['name','portion','kcal','protein','carbs','fat','fiber','sugar','sodium','vitamins'], properties: { name: { type: 'string', minLength: 1, maxLength: 200 }, portion: { type: 'string', minLength: 1, maxLength: 100 }, kcal: { type: 'number', minimum: 0, maximum: 5000 }, protein: { type: 'number', minimum: 0, maximum: 1000 }, carbs: { type: 'number', minimum: 0, maximum: 1000 }, fat: { type: 'number', minimum: 0, maximum: 1000 }, fiber: { type: 'number', minimum: 0, maximum: 1000 }, sugar: { type: 'number', minimum: 0, maximum: 1000 }, sodium: { type: 'number', minimum: 0, maximum: 20000 }, vitamins: { type: 'string', maxLength: 300 } } };
return [{ json: { requestId: body.requestId, openAiBody: { model: 'gpt-5-mini', store: false, input: [{ role: 'user', content }], text: { format: { type: 'json_schema', name: 'nutriverse_food_analysis', strict: true, schema } } } } }];

const response = $json;
let text = response.output_text;
if (!text && Array.isArray(response.output)) { for (const item of response.output) { for (const part of item.content || []) { if (typeof part.text === 'string') { text = part.text; break; } } if (text) break; } }
if (!text) throw new Error('OPENAI_EMPTY_OUTPUT');
const food = JSON.parse(text);
return [{ json: { success: true, food } }];
